<?php
require_once __DIR__.'/../Services/Auditoria.php';
require_once __DIR__.'/Venta.php';

class Reembolso
{
    private $db;
    public function __construct(PDO $db){$this->db=$db;}
    private function puede(array $actor,$tipo){return !empty($actor['permisos']['todo'])||(!empty($actor['permisos']['vender'])&&!empty($actor['permisos']['operar_caja'])&&!empty($actor['permisos'][$tipo==='cancelacion'?'cancelar_venta':'hacer_devoluciones']));}
    private function actor($id,$tipo,$admin=null){
        $this->db->query('SELECT id FROM roles ORDER BY id FOR SHARE')->fetchAll();$ids=array($id);if($admin)$ids[]=$admin['id'];$ids=array_values(array_unique($ids));sort($ids,SORT_NUMERIC);$q=$this->db->prepare('SELECT id FROM usuarios WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY id FOR UPDATE');$q->execute($ids);$q->fetchAll();$a=(new Usuario($this->db))->buscar($id);
        if($admin){$approver=(new Usuario($this->db))->buscar($admin['id']);$hash=(new Auth($this->db))->credencial($admin['id']);if(!$approver||!$approver['activo']||empty($approver['permisos']['todo'])||!hash_equals(hash('sha256',$admin['contrasena_hash']),$hash))throw new HttpError('La autorización del administrador cambió. Solicítala de nuevo.',403);}
        if(!$a||!$a['activo']||!$this->puede($a,$tipo))throw new HttpError('No tienes permiso para esta operación.',403);return $a;
    }
    private function venta($id,array $actor,$lock=false){
        $q=$this->db->prepare('SELECT id,folio,usuario_id,cliente_id,caja_id,turno_id,ubicacion_id,estatus,subtotal,impuesto_total,total,ticket_datos FROM ventas WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute(array($id));$v=$q->fetch();if(!$v)throw new HttpError('Venta no encontrada.',404);
        if(!Venta::veTodas($actor)&&(string)$v['usuario_id']!==(string)$actor['id']&&(!isset($actor['reembolso_folio'])||!hash_equals($v['folio'],$actor['reembolso_folio'])))throw new HttpError('Solo puedes consultar tus propias ventas.',403);
        if($lock&&$v['cliente_id']!==null)(new Credito($this->db))->disponible($v['cliente_id'],true);
        $q=$this->db->prepare("SELECT d.*,u.codigo AS unidad_codigo,COALESCE(d.permite_decimales,u.permite_decimales,0) AS decimales,
            COALESCE(d.controla_inventario,EXISTS(SELECT 1 FROM movimientos_inventario m WHERE m.tipo_referencia='venta' AND m.referencia_id=d.venta_id AND m.variante_id=d.variante_id AND m.tipo_movimiento='venta')) AS inventario
            FROM detalle_venta d LEFT JOIN unidades u ON u.id=d.unidad_id WHERE d.venta_id=? ORDER BY d.id".($lock?' FOR UPDATE':''));$q->execute(array($id));$v['detalles']=$q->fetchAll();
        $q=$this->db->prepare('SELECT d.id,d.detalle_venta_id,d.cantidad,d.subtotal_linea,d.impuesto_linea,d.total_linea FROM detalle_devolucion d JOIN devoluciones_venta r ON r.id=d.devolucion_id WHERE r.venta_id=? ORDER BY d.id'.($lock?' FOR UPDATE':''));$q->execute(array($id));$anteriores=$q->fetchAll();$v['huella_detalles']=$anteriores;$v['devuelto']=0;
        $snapshot=$v['ticket_datos']?json_decode($v['ticket_datos'],true):array();
        foreach($v['detalles'] as &$line){if(isset($snapshot['unidades'][$line['variante_id']]))$line['unidad_codigo']=$snapshot['unidades'][$line['variante_id']];$line['cantidad_devuelta']=0;$line['subtotal_devuelto']=0;$line['impuesto_devuelto']=0;foreach($anteriores as $r){if((string)$r['detalle_venta_id']===(string)$line['id']){$line['cantidad_devuelta']+=Inventario::unidades($r['cantidad']);$line['subtotal_devuelto']+=Caja::centavos($r['subtotal_linea']);$line['impuesto_devuelto']+=Caja::centavos($r['impuesto_linea']);}}$line['pendiente']=Inventario::unidades($line['cantidad'])-$line['cantidad_devuelta'];if($line['pendiente']<0)throw new HttpError('El historial de devoluciones necesita revisión.',409);$v['devuelto']+=$line['subtotal_devuelto']+$line['impuesto_devuelto'];}unset($line);
        $q=$this->db->prepare('SELECT p.id,p.abono_id,p.metodo_pago_id,p.monto,COALESCE(p.tipo_metodo,m.tipo) AS tipo,COALESCE(p.nombre_metodo,m.nombre) AS nombre FROM pagos_venta p JOIN metodos_pago m ON m.id=p.metodo_pago_id WHERE p.venta_id=? ORDER BY p.id'.($lock?' FOR UPDATE':''));$q->execute(array($id));$v['pagos']=$q->fetchAll();
        $q=$this->db->prepare('SELECT p.id,p.pago_venta_id,p.monto FROM pagos_devolucion p JOIN devoluciones_venta r ON r.id=p.devolucion_id WHERE r.venta_id=? ORDER BY p.id'.($lock?' FOR UPDATE':''));$q->execute(array($id));$ref=$q->fetchAll();$v['huella_pagos']=$ref;
        $abonado=0;foreach($v['pagos'] as $p)if($p['abono_id']!==null)$abonado+=Caja::centavos($p['monto']);
        foreach($v['pagos'] as &$p){$p['disponible']=Caja::centavos($p['monto']);foreach($ref as $r)if((string)$r['pago_venta_id']===(string)$p['id'])$p['disponible']-=Caja::centavos($r['monto']);if($p['tipo']==='credito')$p['disponible']-=$abonado;if($p['disponible']<0)throw new HttpError('Los reembolsos del ticket necesitan revisión.',409);}unset($p);return $v;
    }
    public function contexto($id,array $actor){
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$v=$this->venta($id,$actor);$lines=array();foreach($v['detalles'] as $d)$lines[]=array('id'=>$d['id'],'variante_id'=>$d['variante_id'],'descripcion'=>$d['descripcion'],'cantidad'=>$d['cantidad'],'devuelta'=>Inventario::decimal($d['cantidad_devuelta']),'pendiente'=>Inventario::decimal($d['pendiente']),'controla_inventario'=>(bool)$d['inventario'],'permite_decimales'=>(bool)$d['decimales'],'unidad_codigo'=>$d['unidad_codigo']);
            $q=$this->db->prepare("SELECT t.id,c.nombre AS caja_nombre,l.nombre AS ubicacion_nombre,t.ubicacion_id FROM turnos_caja t JOIN cajas c ON c.id=t.caja_id JOIN ubicaciones l ON l.id=COALESCE(t.ubicacion_id,c.ubicacion_id) WHERE t.abierto_por=? AND t.estatus='abierto' AND c.activo=1 AND l.activo=1 AND l.disponible_venta=1 ORDER BY t.id DESC");$q->execute(array($actor['id']));$turnos=$q->fetchAll();
            $result=array('requiere_autorizacion'=>empty($actor['permisos']['todo']),'venta'=>array('id'=>$v['id'],'folio'=>$v['folio'],'estatus'=>$v['estatus'],'total'=>$v['total'],'reembolsado'=>Caja::dinero($v['devuelto']),'neto'=>Caja::dinero(Caja::centavos($v['total'])-$v['devuelto'])),'detalles'=>$lines,'turnos'=>$turnos,
                'resguardos'=>$this->db->query('SELECT id,nombre FROM ubicaciones WHERE activo=1 AND disponible_venta=0 ORDER BY nombre,id')->fetchAll(),
                'puede_devolver'=>$this->puede($actor,'devolucion')&&$v['estatus']==='completada'&&count(array_filter($lines,function($l){return Inventario::unidades($l['pendiente'])>0;}))>0,
                'puede_cancelar'=>$this->puede($actor,'cancelacion')&&$v['estatus']==='completada'&&!$v['huella_detalles']&&in_array($v['turno_id'],array_column($turnos,'id'),true));$this->db->commit();return $result;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    private function conFolio(array $actor,array $datos){
        if(isset($datos['folio'])){
            $folio=is_string($datos['folio'])?strtoupper(trim($datos['folio'])):'';
            if(!preg_match('/^V-[0-9]{8,20}$/D',$folio))throw new HttpError('Escribe el folio completo del ticket, por ejemplo V-00000001.');
            if(!$this->puede($actor,'devolucion')&&!$this->puede($actor,'cancelacion'))throw new HttpError('Necesitas permiso para solicitar devoluciones o cancelaciones.',403);
            $actor['reembolso_folio']=$folio;
        }return $actor;
    }
    public function porFolio(array $datos,array $actor){
        $actor=$this->conFolio($actor,$datos);if(!isset($actor['reembolso_folio']))throw new HttpError('Escribe el folio del ticket.');
        $q=$this->db->prepare('SELECT id FROM ventas WHERE folio=?');$q->execute(array($actor['reembolso_folio']));$id=$q->fetchColumn();if(!$id)throw new HttpError('No se encontró ese folio de venta.',404);
        return $this->contexto($id,$actor);
    }
    private function normalizar(array $d){
        $tipo=isset($d['tipo'])?$d['tipo']:null;if(!in_array($tipo,array('devolucion','cancelacion'),true))throw new HttpError('Selecciona devolución o cancelación.');
        $turno=Producto::identificador(isset($d['turno_id'])?$d['turno_id']:null);$motivo=Producto::texto($d,'motivo',300,true);$lines=array();$seen=array();
        if($tipo==='devolucion'){
            if(!isset($d['detalles'])||!is_array($d['detalles'])||count($d['detalles'])<1||count($d['detalles'])>100)throw new HttpError('Selecciona entre 1 y 100 renglones.');
            foreach($d['detalles'] as $l){if(!is_array($l))throw new HttpError('Revisa las cantidades.');$id=Producto::identificador(isset($l['detalle_venta_id'])?$l['detalle_venta_id']:null);$n=Inventario::unidades(isset($l['cantidad'])?$l['cantidad']:null);$dest=isset($l['destino'])?$l['destino']:'venta';if(!$n||isset($seen[$id])||!in_array($dest,array('venta','resguardo','sin_reingreso'),true))throw new HttpError('Revisa cantidades y destino de cada renglón.');$seen[$id]=true;$lines[]=array('detalle_venta_id'=>$id,'cantidad'=>Inventario::decimal($n),'destino'=>$dest,'ubicacion_id'=>$dest==='resguardo'?Producto::identificador(isset($l['ubicacion_id'])?$l['ubicacion_id']:null):null);}
            usort($lines,function($a,$b){return (int)$a['detalle_venta_id']<=>(int)$b['detalle_venta_id'];});
        }
        return array('tipo'=>$tipo,'turno_id'=>$turno,'motivo'=>$motivo,'detalles'=>$lines);
    }
    private function preparar($id,array $input,array $actor){
        $q=$this->db->prepare('SELECT caja_id,turno_id FROM ventas WHERE id=?');$q->execute(array($id));$origen=$q->fetch();if(!$origen)throw new HttpError('Venta no encontrada.',404);
        $q=$this->db->prepare('SELECT caja_id FROM turnos_caja WHERE id=?');$q->execute(array($input['turno_id']));$box=$q->fetchColumn();if(!$box)throw new HttpError('Turno no encontrado.',404);
        $boxes=array_values(array_unique(array_filter(array($box,$origen['caja_id']))));sort($boxes,SORT_NUMERIC);$q=$this->db->prepare('SELECT id FROM cajas WHERE id IN ('.implode(',',array_fill(0,count($boxes),'?')).') ORDER BY id FOR UPDATE');$q->execute($boxes);$q->fetchAll();
        $turnIds=array_values(array_unique(array_filter(array($input['turno_id'],$origen['turno_id']))));sort($turnIds,SORT_NUMERIC);$q=$this->db->prepare('SELECT * FROM turnos_caja WHERE id IN ('.implode(',',array_fill(0,count($turnIds),'?')).') ORDER BY id FOR UPDATE');$q->execute($turnIds);$turnos=array_column($q->fetchAll(),null,'id');$t=$turnos[$input['turno_id']];
        if((string)$t['abierto_por']!==(string)$actor['id'])throw new HttpError('El reembolso debe registrarse en tu propio turno.',403);if($t['estatus']!=='abierto')throw new HttpError('Abre tu caja antes de registrar el reembolso.',409);
        $q=$this->db->prepare('SELECT c.nombre AS caja_nombre,c.activo,c.ubicacion_id,l.nombre AS ubicacion_nombre,l.activo AS lugar_activo,l.disponible_venta FROM cajas c JOIN ubicaciones l ON l.id=COALESCE(?,c.ubicacion_id) WHERE c.id=?');$q->execute(array($t['ubicacion_id'],$box));$c=$q->fetch();if(!$c['activo']||!$c['lugar_activo']||!$c['disponible_venta'])throw new HttpError('La caja y su ubicación deben estar activas para venta.',409);if($t['ubicacion_id']===null)$t['ubicacion_id']=$c['ubicacion_id'];$t['caja_nombre']=$c['caja_nombre'];$t['ubicacion_nombre']=$c['ubicacion_nombre'];
        $v=$this->venta($id,$actor,true);if($v['estatus']!=='completada')throw new HttpError('La venta ya está cancelada o no está completada.',409);
        $chosen=$input['detalles'];if($input['tipo']==='cancelacion'){
            if((string)$v['turno_id']!==(string)$t['id'])throw new HttpError('Solo puedes cancelar en el turno original abierto. Para turnos cerrados utiliza devolución.',409);if($v['huella_detalles'])throw new HttpError('La venta ya tiene devoluciones. Devuelve únicamente las cantidades pendientes.',409);
            $chosen=array();foreach($v['detalles'] as $l)$chosen[]=array('detalle_venta_id'=>$l['id'],'cantidad'=>$l['cantidad'],'destino'=>'venta','ubicacion_id'=>null);
        }
        $byId=array_column($v['detalles'],null,'id');$locations=array($t['ubicacion_id']);foreach($chosen as $l){if($l['destino']==='resguardo')$locations[]=$l['ubicacion_id'];}$locations=array_values(array_unique($locations));sort($locations,SORT_NUMERIC);
        $q=$this->db->prepare('SELECT id,nombre,activo,disponible_venta FROM ubicaciones WHERE id IN ('.implode(',',array_fill(0,count($locations),'?')).') ORDER BY id FOR SHARE');$q->execute($locations);$places=array_column($q->fetchAll(),null,'id');foreach($locations as $l)if(!isset($places[$l])||!$places[$l]['activo'])throw new HttpError('Selecciona ubicaciones activas.',409);
        $result=array();$sub=0;$tax=0;
        foreach($chosen as $l){if(!isset($byId[$l['detalle_venta_id']]))throw new HttpError('Un renglón no pertenece a esta venta.');$old=$byId[$l['detalle_venta_id']];$n=Inventario::unidades($l['cantidad']);if($n>$old['pendiente'])throw new HttpError('La cantidad supera lo pendiente de devolver. Actualiza el ticket.',409);if(!$old['decimales']&&$n%10000!==0)throw new HttpError('El producto solo permite cantidades enteras.');
            $dest=$old['inventario']?$l['destino']:'sin_reingreso';$location=$dest==='sin_reingreso'?null:($dest==='venta'?$t['ubicacion_id']:$l['ubicacion_id']);if($dest==='resguardo'&&$places[$location]['disponible_venta'])throw new HttpError('Selecciona una ubicación de resguardo.');
            $cum=Inventario::decimal($old['cantidad_devuelta']+$n);$q=$this->db->prepare('SELECT ROUND(CAST(? AS DECIMAL(14,2))*CAST(? AS DECIMAL(14,4))/CAST(? AS DECIMAL(14,4)),2),ROUND(CAST(? AS DECIMAL(14,2))*CAST(? AS DECIMAL(14,4))/CAST(? AS DECIMAL(14,4)),2)');$q->execute(array($old['subtotal_linea'],$cum,$old['cantidad'],$old['impuesto_linea'],$cum,$old['cantidad']));$amount=$q->fetch(PDO::FETCH_NUM);$s=Caja::centavos($amount[0])-$old['subtotal_devuelto'];$i=Caja::centavos($amount[1])-$old['impuesto_devuelto'];if($s<0||$i<0)throw new HttpError('Los importes históricos necesitan revisión.',409);$sub+=$s;$tax+=$i;
            $result[]=array('detalle_venta_id'=>$old['id'],'variante_id'=>$old['variante_id'],'descripcion'=>$old['descripcion'],'cantidad'=>$l['cantidad'],'unidad_codigo'=>$old['unidad_codigo'],'destino'=>$dest,'ubicacion_id'=>$location,'ubicacion_nombre'=>$location?$places[$location]['nombre']:null,'subtotal_linea'=>Caja::dinero($s),'impuesto_linea'=>Caja::dinero($i),'total_linea'=>Caja::dinero($s+$i),'costo_unitario'=>$old['costo_unitario']);
        }
        if(!$result)throw new HttpError('No quedan cantidades por devolver.',409);$total=$sub+$tax;if($total>Caja::MAXIMO||$total>Caja::centavos($v['total'])-$v['devuelto'])throw new HttpError('El reembolso supera el importe pendiente.',409);
        $pagos=array();$pagado=0;foreach($v['pagos'] as $p){if($p['abono_id']===null)$pagado+=Caja::centavos($p['monto']);$pagos[]=array('pago_venta_id'=>$p['id'],'metodo_pago_id'=>$p['metodo_pago_id'],'nombre'=>$p['nombre'],'tipo'=>$p['tipo'],'disponible'=>Caja::dinero($p['disponible']));}if($pagado!==Caja::centavos($v['total']))throw new HttpError('Los pagos de la venta no cuadran. Revisa el ticket antes de devolver.',409);
        usort($pagos,function($a,$b){return ($a['tipo']==='credito'?0:1)<=>($b['tipo']==='credito'?0:1);});
        $seal=hash('sha256',json_encode(array($id,$input,$result,$v['huella_detalles'],$v['huella_pagos'],$pagos)));
        return array('venta'=>$v,'turno'=>$t,'detalles'=>$result,'subtotal'=>Caja::dinero($sub),'impuesto_total'=>Caja::dinero($tax),'total'=>Caja::dinero($total),'pagos'=>$pagos,'sello'=>$seal);
    }
    public function cotizar($id,array $d,$actorId){$input=$this->normalizar($d);$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$actor=$this->conFolio($this->actor($actorId,$input['tipo']),$d);$q=$this->preparar($id,$input,$actor);$q['efectivo_disponible']=(new Caja($this->db))->resumenBloqueado($q['turno'])['esperado'];unset($q['venta'],$q['turno']);foreach($q['detalles'] as &$l)unset($l['costo_unitario']);unset($l);$this->db->commit();return $q;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    public function registrar($id,array $d,$actorId){
        $input=$this->normalizar($d);$key=isset($d['clave'])?$d['clave']:'';$sello=isset($d['sello'])?$d['sello']:'';
        if(!is_string($key)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/D',$key)||!is_string($sello)||!preg_match('/^[a-f0-9]{64}$/D',$sello))throw new HttpError('Cotiza y revisa el reembolso antes de confirmar.');
        $pagos=array();$seen=array();if(!isset($d['reembolsos'])||!is_array($d['reembolsos'])||count($d['reembolsos'])>8)throw new HttpError('Revisa los reembolsos.');foreach($d['reembolsos'] as $p){if(!is_array($p))throw new HttpError('Revisa los reembolsos.');$pago=Producto::identificador(isset($p['pago_venta_id'])?$p['pago_venta_id']:null);$m=Caja::centavos(isset($p['monto'])?$p['monto']:null);if(!$m||isset($seen[$pago]))throw new HttpError('Revisa importes y métodos sin repetir.');$seen[$pago]=true;$pagos[]=array('pago_venta_id'=>$pago,'monto'=>Caja::dinero($m),'referencia'=>Producto::texto($p,'referencia',100,false));}usort($pagos,function($a,$b){return (int)$a['pago_venta_id']<=>(int)$b['pago_venta_id'];});
        $huella=hash('sha256',json_encode(array((string)$id,$input,$pagos,$sello)));
        $actual=(new Usuario($this->db))->buscar($actorId);if(!$actual||!$actual['activo']||!$this->puede($actual,$input['tipo']))throw new HttpError('No tienes permiso para esta operación.',403);
        $admin=null;if(empty($actual['permisos']['todo'])){
            if(!isset($d['autorizacion'])||!is_array($d['autorizacion']))throw new HttpError('Solicita la autorización de un administrador para registrar el reembolso.',403);
            $admin=(new Auth($this->db))->autorizarReembolso($d['autorizacion']);
        }
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();
        try{
            $actor=$this->conFolio($this->actor($actorId,$input['tipo'],$admin),$d);if(empty($actor['permisos']['todo'])&&!$admin)throw new HttpError('Solicita autorización del administrador.',403);$this->db->prepare('INSERT IGNORE INTO solicitudes_reembolso (usuario_id,clave,huella) VALUES (?,?,?)')->execute(array($actorId,$key,$huella));$q=$this->db->prepare('SELECT id,huella,resultado FROM solicitudes_reembolso WHERE usuario_id=? AND clave=? FOR UPDATE');$q->execute(array($actorId,$key));$op=$q->fetch();if(!hash_equals($op['huella'],$huella))throw new HttpError('La solicitud ya se utilizó con otros datos.',409);if($op['resultado']!==null){$this->db->commit();return json_decode($op['resultado'],true);}
            $quote=$this->preparar($id,$input,$actor);if(!hash_equals($quote['sello'],$sello))throw new HttpError('Las devoluciones o el ticket cambiaron. Vuelve a cotizar.',409);$byPay=array_column($quote['pagos'],null,'pago_venta_id');$sum=0;$cash=0;$debt=0;$pendingDebt=0;foreach($quote['pagos'] as $p)if($p['tipo']==='credito')$pendingDebt+=Caja::centavos($p['disponible']);
            foreach($pagos as &$p){$n=Caja::centavos($p['monto']);if(!isset($byPay[$p['pago_venta_id']])||$n>Caja::centavos($byPay[$p['pago_venta_id']]['disponible']))throw new HttpError('El importe supera lo reembolsable por ese método.',409);$p=array_merge($byPay[$p['pago_venta_id']],$p);if($p['tipo']==='credito')$debt+=$n;$sum+=$n;if($p['tipo']==='efectivo')$cash+=$n;}unset($p);
            if($debt!==min($pendingDebt,Caja::centavos($quote['total'])))throw new HttpError('Primero aplica la devolución a la deuda pendiente del ticket. El resto se reembolsa por sus métodos originales.');
            if($sum!==Caja::centavos($quote['total']))throw new HttpError('Los reembolsos deben sumar el importe exacto a devolver.');$t=$quote['turno'];$drawer=(new Caja($this->db))->resumenBloqueado($t);if($cash>max(0,Caja::centavos($drawer['esperado'],true)))throw new HttpError('No hay efectivo suficiente en esta caja para el reembolso.',409);
            $variants=array_values(array_unique(array_column($quote['detalles'],'variante_id')));sort($variants,SORT_NUMERIC);$q=$this->db->prepare('SELECT id FROM variantes_producto WHERE id IN ('.implode(',',array_fill(0,count($variants),'?')).') ORDER BY id FOR UPDATE');$q->execute($variants);$q->fetchAll();
            $autorizador=$admin?(new Usuario($this->db))->buscar($admin['id']):$actor;
            $datos=array('autorizado_por'=>$autorizador['id'],'autorizado_nombre'=>$autorizador['nombre'],'usuario_nombre'=>$actor['nombre'],'caja_nombre'=>$t['caja_nombre'],'ubicacion_nombre'=>$t['ubicacion_nombre'],'venta_folio'=>$quote['venta']['folio']);$metodo=$pagos?$pagos[0]['metodo_pago_id']:($quote['venta']['pagos']?$quote['venta']['pagos'][0]['metodo_pago_id']:null);
            if($metodo===null){$metodo=$this->db->query("SELECT id FROM metodos_pago WHERE tipo<>'credito' ORDER BY id LIMIT 1")->fetchColumn();if(!$metodo)throw new HttpError('Configura un método de pago para registrar el documento.');}
            $this->db->prepare('INSERT INTO devoluciones_venta (folio,venta_id,turno_id,usuario_id,metodo_pago_id,subtotal,impuesto_total,total,motivo,tipo,datos) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute(array('P-'.bin2hex(random_bytes(10)),$id,$t['id'],$actorId,$metodo,$quote['subtotal'],$quote['impuesto_total'],$quote['total'],$input['motivo'],$input['tipo'],json_encode($datos)));$dev=$this->db->lastInsertId();$folio=($input['tipo']==='cancelacion'?'C-':'D-').str_pad($dev,8,'0',STR_PAD_LEFT);$this->db->prepare('UPDATE devoluciones_venta SET folio=? WHERE id=?')->execute(array($folio,$dev));
            foreach($quote['detalles'] as $l){$this->db->prepare('INSERT INTO detalle_devolucion (devolucion_id,detalle_venta_id,cantidad,regresa_inventario,subtotal_linea,impuesto_linea,total_linea,ubicacion_id,destino,ubicacion_nombre) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute(array($dev,$l['detalle_venta_id'],$l['cantidad'],$l['ubicacion_id']!==null?1:0,$l['subtotal_linea'],$l['impuesto_linea'],$l['total_linea'],$l['ubicacion_id'],$l['destino'],$l['ubicacion_nombre']));
                if($l['ubicacion_id']!==null){$q=$this->db->prepare('SELECT cantidad FROM existencias WHERE ubicacion_id=? AND variante_id=? FOR UPDATE');$q->execute(array($l['ubicacion_id'],$l['variante_id']));$old=$q->fetchColumn();$saldo=($old===false?0:Inventario::unidades($old,true))+Inventario::unidades($l['cantidad']);if(abs($saldo)>Inventario::MAXIMO)throw new HttpError('El reingreso supera el límite de inventario.');$this->db->prepare('INSERT INTO existencias (ubicacion_id,variante_id,cantidad) VALUES (?,?,?) ON DUPLICATE KEY UPDATE cantidad=cantidad+?')->execute(array($l['ubicacion_id'],$l['variante_id'],$l['cantidad'],$l['cantidad']));$this->db->prepare("INSERT INTO movimientos_inventario (ubicacion_id,variante_id,tipo_movimiento,cantidad,costo_unitario,tipo_referencia,referencia_id,usuario_id,notas) VALUES (?,?,'devolucion_cliente',?,?,'devolucion_venta',?,?,?)")->execute(array($l['ubicacion_id'],$l['variante_id'],$l['cantidad'],$l['costo_unitario'],$dev,$actorId,$folio.' · '.$quote['venta']['folio']));}
            }
            foreach($pagos as $p)$this->db->prepare('INSERT INTO pagos_devolucion (devolucion_id,pago_venta_id,monto,tipo_metodo,nombre_metodo,referencia) VALUES (?,?,?,?,?,?)')->execute(array($dev,$p['pago_venta_id'],$p['monto'],$p['tipo'],$p['nombre'],$p['referencia']));
            if($input['tipo']==='cancelacion')$this->db->prepare("UPDATE ventas SET estatus='cancelada' WHERE id=?")->execute(array($id));
            $result=array('devolucion_id'=>$dev,'venta_id'=>(string)$id,'folio'=>$folio,'tipo'=>$input['tipo'],'total'=>$quote['total']);$this->db->prepare('UPDATE solicitudes_reembolso SET devolucion_id=?,resultado=? WHERE id=?')->execute(array($dev,json_encode($result),$op['id']));Auditoria::operacion($this->db,'reembolso',$dev);$this->db->commit();return $result;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function listar($id,array $actor,array $filtros){
        $this->venta($id,$actor);$args=array($id);$where='r.venta_id=?';if(isset($filtros['antes_de'])&&$filtros['antes_de']!==''){$where.=' AND r.id<?';$args[]=Producto::identificador($filtros['antes_de']);}$q=$this->db->prepare('SELECT r.id,r.folio,r.tipo,r.total,r.motivo,r.datos,UNIX_TIMESTAMP(r.creado_en) AS creado_unix,u.nombre AS usuario_nombre FROM devoluciones_venta r JOIN usuarios u ON u.id=r.usuario_id WHERE '.$where.' ORDER BY r.id DESC LIMIT 21');$q->execute($args);$rows=$q->fetchAll();$more=count($rows)>20;if($more)array_pop($rows);
        foreach($rows as &$r){$datos=$r['datos']?json_decode($r['datos'],true):array();$r['usuario_nombre']=isset($datos['usuario_nombre'])?$datos['usuario_nombre']:$r['usuario_nombre'];$r['caja_nombre']=isset($datos['caja_nombre'])?$datos['caja_nombre']:'';$r['autorizado_nombre']=isset($datos['autorizado_nombre'])?$datos['autorizado_nombre']:null;unset($r['datos']);$q=$this->db->prepare('SELECT d.cantidad,d.destino,d.total_linea,v.descripcion,COALESCE(d.ubicacion_nombre,l.nombre) AS ubicacion_nombre FROM detalle_devolucion d JOIN detalle_venta v ON v.id=d.detalle_venta_id LEFT JOIN ubicaciones l ON l.id=d.ubicacion_id WHERE d.devolucion_id=? ORDER BY d.id');$q->execute(array($r['id']));$r['detalles']=$q->fetchAll();$q=$this->db->prepare('SELECT monto,tipo_metodo,nombre_metodo,referencia FROM pagos_devolucion WHERE devolucion_id=? ORDER BY id');$q->execute(array($r['id']));$r['pagos']=$q->fetchAll();}unset($r);return array('documentos'=>$rows,'siguiente'=>$more?$rows[count($rows)-1]['id']:null);
    }
